{
  "name": "@kungfusaini/opencode-projects",
  "version": "0.2.4",
  "description": "OpenCode plugin for project contexts, streams, durable plans, and worklog continuity.",
  "type": "module",
  "license": "MIT",
  "author": "Sumeet Saini",
  "homepage": "https://github.com/kungfusaini/opencode-projects#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/kungfusaini/opencode-projects.git"
  },
  "bugs": {
    "url": "https://github.com/kungfusaini/opencode-projects/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "worklog",
    "plans",
    "agent-memory"
  ],
  "exports": {
    ".": "./src/index.js",
    "./server": "./src/index.js",
    "./tui": "./src/tui.js"
  },
  "main": "./src/index.js",
  "files": [
    "src/",
    "README.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "check": "node --check src/plan-agent.js && node --check src/worklog.js && node --check src/plans.js && node --check src/projects.js && node --check src/index.js && node --check src/tui.js"
  },
  "dependencies": {
    "@opencode-ai/plugin": "latest",
    "@opentui/solid": "0.3.4",
    "solid-js": "1.9.12"
  },
  "engines": {
    "node": ">=20"
  }
}
